import { createHash, randomBytes, randomUUID } from "node:crypto";

import { getDb } from "@/lib/db";
import { mailMessage, signupRequest } from "@/lib/schema";
import { parseSignupInput } from "@/lib/signup";
import { verifyTurnstile } from "@/lib/turnstile";

function json(body: unknown, status = 200) {
  return Response.json(body, { status, headers: { "Cache-Control": "no-store" } });
}

type SignupDependencies = {
  getDb: typeof getDb;
  verifyTurnstile: typeof verifyTurnstile;
};

export function createSignupHandler(overrides: Partial<SignupDependencies> = {}) {
  const database = overrides.getDb ?? getDb;
  const validateTurnstile = overrides.verifyTurnstile ?? verifyTurnstile;

  return async function POST(request: Request) {
    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return json({ error: "Submit the form again." }, 400);
    }

    const parsed = parseSignupInput(body);
    if (!parsed.data) return json({ errors: parsed.errors }, 422);
    const { turnstileToken, ...requestData } = parsed.data;
    if (!(await validateTurnstile(turnstileToken, request))) {
      return json({ errors: { turnstileToken: "Verification failed. Please try again." } }, 403);
    }
    if (process.env.MAIL_CAPTURE !== "true") {
      return json({ error: "Signup is temporarily unavailable." }, 503);
    }

    const appUrl = process.env.APP_URL;
    if (!appUrl) return json({ error: "Signup is temporarily unavailable." }, 503);

    const requestId = randomUUID();
    const messageId = randomUUID();
    const verificationToken = randomBytes(32).toString("base64url");
    const verificationTokenHash = createHash("sha256").update(verificationToken).digest("hex");
    const verificationExpiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);
    const verificationUrl = new URL(`/verify?token=${verificationToken}`, appUrl).toString();

    try {
      const db = database();
      await db.batch([
        db.insert(signupRequest).values({
          id: requestId,
          ...requestData,
          verificationTokenHash,
          verificationExpiresAt,
        }),
        db.insert(mailMessage).values({
          id: messageId,
          signupRequestId: requestId,
          to: parsed.data.contactEmail,
          subject: "Verify your Workspace signup request",
          text: `Verify your contact email within 24 hours: ${verificationUrl}`,
        }),
      ]);
    } catch (error) {
      if (typeof error === "object" && error && "code" in error && error.code === "23505") {
        return json({ error: "An active signup request already uses this contact email." }, 409);
      }
      return json({ error: "Signup is temporarily unavailable. Please try again." }, 503);
    }

    return json(
      { message: "Your signup request was received. Check your contact email to verify it." },
      201,
    );
  };
}

export const POST = createSignupHandler();

import { z } from "zod";

const optionalText = (maxLength: number, message: string) =>
  z
    .string()
    .trim()
    .max(maxLength, message)
    .optional()
    .transform((value) => value || null);

const signupSchema = z.object({
  givenName: z.string().trim().min(1, "Enter your given name.").max(100, "Enter your given name."),
  familyName: z
    .string()
    .trim()
    .min(1, "Enter your family name.")
    .max(100, "Enter your family name."),
  contactEmail: z
    .string()
    .trim()
    .toLowerCase()
    .max(254, "Enter a valid contact email.")
    .email("Enter a valid contact email."),
  phone: optionalText(50, "Enter a phone number of 50 characters or fewer."),
  connection: optionalText(1000, "Keep your connection explanation to 1,000 characters or fewer."),
  turnstileToken: z
    .string()
    .min(1, "Complete the verification challenge.")
    .max(2048, "Complete the verification challenge."),
});

export type SignupInput = z.output<typeof signupSchema>;
export type SignupErrors = Partial<Record<keyof SignupInput, string>>;

export function parseSignupInput(
  value: unknown,
): { data: SignupInput; errors: undefined } | { data: undefined; errors: SignupErrors } {
  const result = signupSchema.safeParse(value);
  if (result.success) return { data: result.data, errors: undefined };

  const errors: SignupErrors = {};
  for (const issue of result.error.issues) {
    const field = issue.path[0];
    if (
      typeof field === "string" &&
      field in signupSchema.shape &&
      !errors[field as keyof SignupInput]
    ) {
      errors[field as keyof SignupInput] = issue.message;
    }
  }
  return { data: undefined, errors };
}

